  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C09","C15","C16","C07","C10","C17","C30","C33","C35","C44","C45","C49","C51","C52","C53","C55","C71","C74","C77"],
  "contradictory_card_ids": ["C63","C69","C70","C73","C80","C60","C61","C64","C67"],
  "prediction_basis_card_ids": ["C09","C15","C16","C07","C10","C17","C30","C33","C35","C44","C45","C49","C51","C52","C53","C55","C71","C74","C77"],
  "claims": [
    {
      "claim": "The query structure corresponds to itraconazole; no direct absolute oral bioavailability measurement for itraconazole is present in the supplied records, but fed-state absolute F values for ziprasidone (~59–60%) and food-insensitive sertindole (~74–75%) show that lipophilic, poorly soluble drugs can meet F ≥ 20% under fed conditions.",
      "card_ids": ["C09","C15","C16","C07","C10","C17","C30"]
    },
    {
      "claim": "Oral exposure and permeability records for azole analogs posaconazole and ketoconazole show substantial systemic absorption (posaconazole Cmax ~605–851 ng/mL, AUC up to 8619 ng·h/mL; Caco-2 Papp ~3.4–4.0 × 10^-5 cm/s), supporting adequate absorption for the azole/dioxolane/piperazine scaffold.",
      "card_ids": ["C33","C35","C44","C45","C49","C51","C52","C53","C55","C34"]
    },
    {
      "claim": "L6 C69 directly identifies itraconazole as hepatically metabolized and a CYP substrate/inhibitor; ketoconazole records show moderate-to-high hepatic extraction/CLint (HER 0.6; CLint,max 402 µl/(min/mg)), indicating possible presystemic loss, but these are mechanism-only and do not establish F < 20%.",
      "card_ids": ["C69","C70","C73","C80"]
    },
    {
      "claim": "Posaconazole PBPK hepatic escape fractions (Fh 0.90–0.94) and low CYP/UGT metabolism records show that some azoles have high hepatic escape, but transferability to itraconazole is limited because itraconazole is more extensively metabolized; overall no affirmative threshold-relevant low-F evidence is present.",
      "card_ids": ["C71","C74","C77","C78","C79"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C69","C70","C73","C80"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is provided for itraconazole or a structurally identical analog.",
    "L6 records are mostly posaconazole/ketoconazole; no itraconazole-specific hepatic clearance, extraction ratio, or Fh value is available.",
    "No matched oral-versus-IV exposure comparison is available for itraconazole.",
    "Fed-state formulation, dose, and food composition for the query are unspecified.",
    "No quantitative efflux ratio or intestinal CYP3A4 metabolism rate is available for itraconazole.",
    "Transferability from posaconazole/ketoconazole is inferred from shared azole/dioxolane/piperazine scaffold, not a direct F measurement."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) under fed state. Fed-state F records for ziprasidone/sertindole, substantial oral exposure and high Caco-2 permeability for azole analogs support adequate absorption; L6 hepatic metabolism/clearance records add a negative mechanistic signal for presystemic loss but are not direct F measurements and do not establish F < 20%. Confidence remains low because no direct itraconazole F measurement is available and the negative hepatic/efflux mechanisms add uncertainty."
}

